sealed class ChallengeProgress {
 public readonly Dictionary<int,double> Scores=new Dictionary<int,double>();
 public readonly string Root;public int AttemptLevel;public DateTime Deadline;
 public int Unlocked{get{int n=1;while(n<=50&&Scores.ContainsKey(n)&&Scores[n]>90)n++;return Math.Min(50,n);}}
 public int PassedCount{get{return Scores.Count(x=>x.Value>90);}}
 public ChallengeProgress(string root){Root=Path.Combine(root,"challenge-ver1.2.1");Directory.CreateDirectory(Root);try{foreach(string s in File.ReadAllLines(Path.Combine(Root,"scores.tsv"))){string[] a=s.Split('\t');int n;double v;if(a.Length==2&&int.TryParse(a[0],out n)&&double.TryParse(a[1],NumberStyles.Float,CultureInfo.InvariantCulture,out v)&&n>=1&&n<=50&&v>=0&&v<=100)Scores[n]=v;}}catch{}try{string[] a=File.ReadAllText(Path.Combine(Root,"attempt.tsv")).Split('\t');int n;long t;if(a.Length==2&&int.TryParse(a[0],out n)&&long.TryParse(a[1],out t)&&n>=1&&n<=Unlocked){AttemptLevel=n;Deadline=new DateTime(t,DateTimeKind.Utc);}}catch{}}
 public bool Passed(int n){return Scores.ContainsKey(n)&&Scores[n]>90;}
 public static bool Qualifies(Evaluation ev){return ev!=null&&ev.Compiled&&ev.Score>90&&ev.Cases.Count==28&&ev.Cases.All(c=>c.Run.Failure==""&&c.Run.ExitCode==0);}
 public void Record(int n,Evaluation ev){if(n>Unlocked||n<1)throw new InvalidOperationException("该关尚未解锁。");double v=Qualifies(ev)?ev.Score:Math.Min(90,ev.Score);if(!Scores.ContainsKey(n)||v>Scores[n])Scores[n]=v;Atomic("scores.tsv",string.Join("\n",Scores.OrderBy(x=>x.Key).Select(x=>x.Key+"\t"+x.Value.ToString(CultureInfo.InvariantCulture)).ToArray()));}
 public void Begin(int n,int seconds){if(n>Unlocked)throw new InvalidOperationException("该关尚未解锁。");AttemptLevel=n;Deadline=DateTime.UtcNow.AddSeconds(seconds);SaveAttempt();}
 public void End(){AttemptLevel=0;Deadline=DateTime.MinValue;SaveAttempt();}
 public void Extend(TimeSpan duration){if(AttemptLevel>0){Deadline=Deadline.Add(duration);SaveAttempt();}}
 void SaveAttempt(){Atomic("attempt.tsv",AttemptLevel+"\t"+Deadline.Ticks);}
 void Atomic(string name,string text){string path=Path.Combine(Root,name),tmp=path+".tmp";File.WriteAllText(tmp,text,new UTF8Encoding(false));if(File.Exists(path))File.Replace(tmp,path,null);else File.Move(tmp,path);}
 public string Draft(int n){string file=Path.Combine(Root,n.ToString("00")+".c");return File.Exists(file)?File.ReadAllText(file,Encoding.UTF8):"";}
 public void SaveDraft(int n,string code){Atomic(n.ToString("00")+".c",code);}
}
