 void RefreshMap(){map.Refresh(state);stats.Text="已点亮 "+state.PassedCount+" / 50    ·    总分 "+state.Scores.Values.Sum().ToString("0.#")+" / 5000";}
  public void Select(int n){if(n<1||n>50||busy)return;if(level!=null&&level.Number==n)return;if(n>state.Unlocked){status.Text="该星点尚未解锁，先完成前一关（>90分）。";return;}if(active&&level!=null&&level.Number!=n){status.Text="当前挑战仍在计时，请完成或结束本次挑战。";map.SetSelected(level.Number);return;}SaveDraft();level=ChallengeBank.Levels[n-1];loading=true;editor.Text=state.Draft(n);editor.Input.Document.UndoStack.ClearAll();loading=false;evaluation=null;cases.Items.Clear();score.Text="—";heading.Text="第 "+n.ToString("00")+" 关 · "+level.Problem.Title;chapter.Text=level.Problem.Category+"  /  限时 "+Format(level.Seconds)+"  /  >90 分才能进入下一关";var example=ChallengeBank.Generate(100+n,new Random(202611),-1);requirement.Text=level.Problem.Statement+"\n\n示例输入："+example.Input.TrimEnd()+"\n示例输出："+example.Expected.TrimEnd();map.SetSelected(n);active=state.AttemptLevel==n;deadline=state.Deadline;clock.Text=Format(level.Seconds);timeBar.Value=1;output.Text="完整答案锁定至通关。\n本关所有代码由你键入，支持多步撤回和重做。";status.Text=active?"已恢复本次挑战截止时间":"先学习，再开始倒计时";UpdateActions();if(active){timer.Start();Tick();}Fade(playArea);}
 static string Format(int seconds){seconds=Math.Max(0,seconds);return (seconds/60).ToString("00")+":"+(seconds%60).ToString("00");}
 static void Fade(UIElement element){element.BeginAnimation(OpacityProperty,new DoubleAnimation(.1,1,TimeSpan.FromMilliseconds(380)){EasingFunction=new CubicEase{EasingMode=EasingMode.EaseOut}});}
 void UpdateActions(){editor.Input.IsReadOnly=!active||busy;editor.UpdateHistory();submit.IsEnabled=active&&!busy;start.IsEnabled=!busy;start.Content=active?"结束本次挑战":"开始 / 重试";stop.IsEnabled=busy;map.SelectionLocked=active||busy;knowledge.IsEnabled=!busy;answer.IsEnabled=state.Passed(level.Number)&&!busy;next.IsEnabled=state.Passed(level.Number)&&level.Number<50&&!busy&&!active;}
 void Begin(){if(busy)return;if(active){SaveDraft();state.End();active=false;timer.Stop();status.Text="本次挑战已结束，可重新开始";UpdateActions();return;}state.Begin(level.Number,level.Seconds);deadline=state.Deadline;active=true;evaluation=null;cases.Items.Clear();score.Text="—";output.Text="倒计时开始。独立完成程序后提交。";status.Text="挑战进行中 · 学习和切换窗口时继续计时";timer.Start();Tick();UpdateActions();editor.Input.Focus();}
 public void Tick(){if(!active||busy||closed)return;int remain=(int)Math.Ceiling((deadline-DateTime.UtcNow).TotalSeconds);clock.Text=Format(remain);timeBar.Value=Math.Max(0,remain)/(double)level.Seconds;clock.Foreground=remain<=30?Theme.B("#FF5368"):Dark.Accent;if(remain<=0){active=false;timer.Stop();SaveDraft();state.End();output.Text="时间耗尽，本次挑战失败。你的代码已保存，可以重试。";status.Text="限时结束 · 本次未通关";score.Text="0";UpdateActions();new FailureWindow("倒计时耗尽 · 封印未解除"){Owner=this}.ShowDialog();}}
 public async Task Judge(){if(!active||busy)return;if(DateTime.UtcNow>=deadline){Tick();return;}SaveDraft();string submittedCode=editor.Text;DateTime judgeStarted=DateTime.UtcNow;busy=true;timer.Stop();UpdateActions();score.Text="…";output.Text="正在编译并评测28组数据…";cases.Items.Clear();cancellation=new CancellationTokenSource();int seed;using(var rng=System.Security.Cryptography.RandomNumberGenerator.Create()){byte[] b=new byte[4];rng.GetBytes(b);seed=BitConverter.ToInt32(b,0)&int.MaxValue;}try{var ev=await Task.Run(()=>Engine.Judge(level.Problem,submittedCode,seed,cancellation.Token,(a,b)=>{if(!closed)Dispatcher.BeginInvoke((Action)(()=>status.Text="评测 "+a+" / "+b+" · 提交时限已满足"));}));evaluation=ev;state.Record(level.Number,ev);score.Text=ev.Score.ToString("0.#")+" 分";Populate();if(ChallengeProgress.Qualifies(ev)){active=false;state.End();status.Text=level.Number==50?"50道封印全部解除 · 终局通关":"通关！下一关已解锁 · 可阅读复盘答案";RefreshMap();var anim=new DoubleAnimation(1,1.22,TimeSpan.FromMilliseconds(220)){AutoReverse=true,EasingFunction=new CubicEase{EasingMode=EasingMode.EaseOut}};var scale=new ScaleTransform(1,1);score.RenderTransformOrigin=new Point(.5,.5);score.RenderTransform=scale;scale.BeginAnimation(ScaleTransform.ScaleXProperty,anim);scale.BeginAnimation(ScaleTransform.ScaleYProperty,anim);Fade(playArea);}else if(FailureWindow.ShouldPlay(ev)){active=false;state.End();status.Text="本次挑战失败 · 代码已保留，可重新开始";new FailureWindow(FailureWindow.Reason(ev)){Owner=this}.ShowDialog();}else{status.Text="尚未超过90分 · 可在剩余时间内改进并再次提交";}}
  catch(OperationCanceledException){status.Text="已停止评测 · 倒计时继续";output.Text="评测已停止，没有计算成绩。";score.Text="—";}catch(Exception ex){status.Text="评测环境或存储异常";output.Text=ex.Message;score.Text="—";}finally{if(active){try{state.Extend(DateTime.UtcNow-judgeStarted);deadline=state.Deadline;}catch(Exception ex){status.Text="计时保存失败："+ex.Message;}}busy=false;cancellation.Dispose();cancellation=null;UpdateActions();if(active){timer.Start();Tick();}}
 }
 void Populate(){if(!evaluation.Compiled){output.Text=Theme.CompileAdvice(evaluation.Compiler,false);return;}for(int i=0;i<evaluation.Cases.Count;i++)cases.Items.Add("用例 "+(i+1)+" · "+(evaluation.Cases[i].Passed?"通过":"失败"));cases.SelectedIndex=Math.Max(0,evaluation.Cases.FindIndex(c=>!c.Passed));}
 void ShowCase(){if(evaluation==null||cases.SelectedIndex<0)return;var c=evaluation.Cases[cases.SelectedIndex];output.Text="输入\n"+c.Test.Input.TrimEnd()+"\n\n实际输出\n"+(c.Run.Output==""?"（无输出）":c.Run.Output.TrimEnd())+"\n\n预期输出\n"+c.Test.Expected.TrimEnd()+"\n\n诊断\n"+c.Diagnosis+"\n\n耗时 "+c.Run.Millis.ToString("0.0")+" ms · 退出码 "+c.Run.ExitCode+"\n\n标准错误 / 中文解释\n"+Diagnostics.Explain(c.Run.Error)+"\n\n编译信息 / 中文解释\n"+Theme.CompileAdvice(evaluation.Compiler,true);}
 public void ShowKnowledge(){ShowText("第 "+level.Number+" 关 · 知识点学习",level.Learning);}
 void ShowText(string title,string text){var w=new Window{Title=title,Owner=this,Width=760,Height=620,MinWidth=560,MinHeight=380,WindowStartupLocation=WindowStartupLocation.CenterOwner};Theme.Window(w,true);var grid=new Grid{Margin=new Thickness(20)};grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.Children.Add(Dark.Text(title,20,true));var read=Dark.Read(text);read.FontFamily=w.FontFamily;read.FontSize=14;read.Margin=new Thickness(0,14,0,14);Grid.SetRow(read,1);grid.Children.Add(read);var close=Dark.Button("返回挑战");close.IsCancel=true;close.HorizontalAlignment=HorizontalAlignment.Right;close.Click+=(s,e)=>w.Close();Grid.SetRow(close,2);grid.Children.Add(close);w.Background=Dark.Bg;w.Content=grid;w.ShowDialog();}
 public bool CanViewAnswer{get{return level!=null&&state.Passed(level.Number);}}
 public void ShowReference(){if(!CanViewAnswer||busy)return;var w=new Window{Title="通关复盘 · "+level.Problem.Title,Owner=this,Width=900,Height=720,WindowStartupLocation=WindowStartupLocation.CenterOwner};Theme.Window(w,true);var grid=new Grid{Margin=new Thickness(18)};grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});grid.Children.Add(Dark.Text("通关复盘 · 仅阅读，无答案导入",16,true));var code=new CodeEditor{Margin=new Thickness(0,14,0,0)};code.SetDark();code.Text=level.Problem.Reference;code.Input.IsReadOnly=true;Grid.SetRow(code,1);grid.Children.Add(code);w.Background=Dark.Bg;w.Content=grid;w.ShowDialog();}
 void SaveDraft(){if(loading||level==null||editor==null)return;try{state.SaveDraft(level.Number,editor.Text);}catch(Exception ex){if(status!=null)status.Text="草稿保存失败："+ex.Message;}}
 void EditorKeys(object s,KeyEventArgs e){if(editor.HandleHistory(e))return;if((Keyboard.Modifiers&ModifierKeys.Control)!=0&&e.Key==Key.Enter){e.Handled=true;Dispatcher.BeginInvoke((Action)(async()=>await Judge()));return;}if((Keyboard.Modifiers&ModifierKeys.Control)!=0&&(e.Key==Key.V||e.Key==Key.X)||Keyboard.Modifiers==ModifierKeys.Shift&&e.Key==Key.Insert){e.Handled=true;status.Text="闯关代码需自主键入。";return;}if(editor.Input.IsReadOnly)return;if(e.Key==Key.Tab){e.Handled=true;editor.Input.SelectedText="    ";}else if(e.Key==Key.Enter&&Keyboard.Modifiers==ModifierKeys.None){e.Handled=true;int pos=editor.Input.SelectionStart;int line=editor.Input.GetLineIndexFromCharacterIndex(pos),from=editor.Input.GetCharacterIndexFromLineIndex(line);string before=editor.Text.Substring(from,pos-from);string indent=System.Text.RegularExpressions.Regex.Match(before,@"^[ \t]*").Value;if(before.TrimEnd().EndsWith("{"))indent+="    ";editor.Input.SelectedText="\n"+indent;}}
 void ClosingGame(object s,CancelEventArgs e){if(busy){if(cancellation!=null)cancellation.Cancel();e.Cancel=true;status.Text="正在停止评测，请稍后再关闭";return;}SaveDraft();}
 public void PreviewSize(double width,double height){WindowState=WindowState.Normal;root.Width=width;root.Height=height;SizeToContent=SizeToContent.WidthAndHeight;UpdateLayout();}
 // Test hooks exercise the same editor, timer, judge and gates used by the UI.
 public CodeEditor Editor{get{return editor;}}public ChallengeProgress Progress{get{return state;}}
 public void StartForCheck(){Begin();}public void ExpireForCheck(){deadline=DateTime.UtcNow.AddSeconds(-1);Tick();}
